using System.Collections.Generic;
using UnityEngine;

namespace ND_BehaviorTree.Story
{
    /// <summary>
    /// One branch of a <see cref="StorySwitchNode"/>, generated by the Switch from its case list (not created by hand).
    /// Holds the case value and passes execution to its single child; an empty case succeeds.
    /// </summary>
    [NodeDescription("A Switch branch (generated from the Switch's case list). Connect the branch below it.",
        "Created, renamed and removed by its Switch: edit the Switch's 'Cases' list. Runs its child; with no child it succeeds.")]
    [NodeInfo("Case", "Story/Case", true, true, isChildOnly: true)]
    public class StoryCaseNode : Node
    {
        public string caseValue;
        public bool isDefault;
        [HideInInspector] public Node child;

        public string Label => isDefault ? "Default" : caseValue;

        protected override Status OnProcess() => child != null ? child.Process() : Status.Success;

        public override void Reset()
        {
            base.Reset();
            child?.Reset();
        }

        public override Node Clone()
        {
            var node = (StoryCaseNode)base.Clone();
            node.child = null; // rewired by BehaviorTree.Clone
            return node;
        }

        public override void AddChild(Node newChild) => child = newChild;

        public override void RemoveChild(Node childToRemove)
        {
            if (child == childToRemove) child = null;
        }

        public override List<Node> GetChildren() => child != null ? new List<Node> { child } : new List<Node>();
    }
}
